<script>
  import { base } from '$app/paths';
  import { page } from '$app/stores';
  import { onMount } from 'svelte';
  let state={config:{repositories:[],apps:[],integrations:[],githubAccounts:[],publicHost:'',githubOAuthClientId:'',notifications:{},updateChecks:{interval:86400,lastCheck:null}},status:{},catalog:[]};
  let githubRepos=[], accountId='', oauthClientId='', device=null, poller, repository='', publicRepository='', repoDialog=false, repoMode='public';
  let haNotifications={connected:false,notifyServices:[]};
  let message='', failure='';
  $: view=$page.url.pathname.replace(base,'').split('/').filter(Boolean)[0]||'dashboard';
  $: official=state.catalog;
  $: external=state.config.repositories.flatMap(repo=>(repo.applications||[]).map(app=>({...app,source:repo.fullName})));
  async function api(path,options={}){const response=await fetch(`${base}/api/${path}`,{headers:{'Content-Type':'application/json'},...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||data.error||`HTTP ${response.status}`);return data}
  async function refresh(){state=await api('state')}
  async function run(fn,text='Saved'){failure='';try{await fn();message=text;await refresh()}catch(error){failure=error.message}}
  onMount(()=>{refresh();api('ha/notifications').then(value=>haNotifications=value).catch(()=>{});const timer=setInterval(refresh,3000);return()=>{clearInterval(timer);clearInterval(poller)}});
  async function addRepo(fullName=repository,selectedAccount=accountId){repoDialog=false;await run(()=>api('repositories',{method:'POST',body:JSON.stringify({fullName,accountId:selectedAccount})}),'Repository added and scan queued.')}
  async function removeRepo(event,fullName){event.stopPropagation();if(!confirm(`Remove ${fullName} from X Platform? Installed integrations remain managed.`))return;await run(()=>api('repositories',{method:'DELETE',body:JSON.stringify({fullName})}),'Repository removed.')}
  async function loadRepos(){githubRepos=await api(`github?account=${encodeURIComponent(accountId)}`)}
  async function saveOAuth(){await run(()=>api('settings',{method:'PUT',body:JSON.stringify({githubOAuthClientId:oauthClientId})}))}
  async function deviceLogin(){device=await api('github/device',{method:'POST',body:JSON.stringify({action:'start'})});window.open(device.verification_uri,'_blank');poller=setInterval(async()=>{const result=await api('github/device',{method:'POST',body:JSON.stringify({action:'poll',deviceCode:device.device_code})});if(result.connected){clearInterval(poller);device=null;await refresh()}},Math.max(5,device.interval||5)*1000)}
  function counts(repo){return `${repo.integrations?.length||0} integrations Â· ${repo.applications?.length||0} applications`}
  function asset(item,kind){const repository=item.repository||item.source;return item?.[kind]&&repository?`${base}/api/assets?repository=${encodeURIComponent(repository)}&path=${encodeURIComponent(item[kind])}`:''}
  async function saveNotifications(){await run(()=>api('settings',{method:'PUT',body:JSON.stringify({notifications:state.config.notifications})}),'Notification preferences saved.')}
  async function saveUpdateInterval(){await run(()=>api('settings',{method:'PUT',body:JSON.stringify({updateChecks:state.config.updateChecks})}),'Update check schedule saved.')}
  function toggleService(service){const selected=state.config.notifications.notifyServices||[];state.config.notifications.notifyServices=selected.includes(service)?selected.filter(item=>item!==service):[...selected,service];state={...state}}
  $: running=state.config.apps.filter(app=>state.status[app.id]?.state==='running').length;
  $: broken=state.config.apps.filter(app=>state.status[app.id]?.state==='error').length;
  $: installedIntegrations=state.config.integrations.filter(item=>item.installed).length;
  $: availableUpdates=state.config.integrations.filter(item=>item.installed&&item.version&&item.installedVersion!==item.version).length+state.config.apps.filter(item=>state.status[item.id]?.updateAvailable).length;
</script>
  {#if message}<div class="flash">{message}</div>{/if}{#if failure}<div class="flash bad">{failure}</div>{/if}
  {#if view==='dashboard'}
    {#if availableUpdates}<div class="update-banner"><b>{availableUpdates} update{availableUpdates===1?'':'s'} available</b><span>Review integrations and applications before installing.</span></div>{/if}
    <section class="metrics"><article><small>Applications</small><b>{running}<i> / {state.config.apps.length}</i></b><p>currently running</p></article><article><small>Integrations</small><b>{installedIntegrations}<i> / {state.config.integrations.length}</i></b><p>installed and managed</p></article><article><small>Repositories</small><b>{state.config.repositories.length}</b><p>connected sources</p></article><article class:metric-danger={broken>0}><small>Errors</small><b>{broken}</b><p>applications need attention</p></article></section>
    <div class="dashboard-grid"><section><h2>Application health</h2><div class="table"><table><thead><tr><th>Application</th><th>Status</th><th>Port</th></tr></thead><tbody>{#each state.config.apps as app}<tr on:click={()=>location.href=`${base}/application?id=${encodeURIComponent(app.id)}`}><td><b>{app.name}</b></td><td><span class:ok={state.status[app.id]?.state==='running'}>{state.status[app.id]?.state||'stopped'}</span></td><td>{app.port}</td></tr>{:else}<tr><td colspan="3" class="empty">Install your first application from Discover.</td></tr>{/each}</tbody></table></div></section><section><h2>Repository health</h2><div class="table"><table><thead><tr><th>Repository</th><th>Scan</th></tr></thead><tbody>{#each state.config.repositories as repo}<tr on:click={()=>location.href=`${base}/repository?id=${encodeURIComponent(repo.fullName)}`}><td><b>{repo.fullName}</b><small>{counts(repo)}</small></td><td>{repo.scanState||'waiting'}</td></tr>{:else}<tr><td colspan="2" class="empty">No repositories added yet.</td></tr>{/each}</tbody></table></div></section></div>
  {:else if view==='discover'}
    <h2>Official collection</h2><section class="poster-grid">{#each official as item}<a href={`${base}/application?id=${item.id}&catalog=1`}><div class="poster" class:has-image={asset(item,'background')} style:background-image={asset(item,'background')?`linear-gradient(0deg,#090c12cc,#090c1222),url('${asset(item,'background')}')`:''}>{#if asset(item,'icon')}<img src={asset(item,'icon')} alt=""/>{:else}<span>{item.name.slice(0,1)}</span>{/if}<small>OFFICIAL</small></div><h3>{item.name}</h3><p>{item.description}</p><div><span>Node.js</span><span>Port {item.port}</span></div></a>{/each}</section>
    <h2>From your repositories</h2><section class="poster-grid compact">{#each external as item}<a href={`${base}/application?id=${item.id}&repository=${encodeURIComponent(item.source)}`}><div class="poster external" class:has-image={asset(item,'background')} style:background-image={asset(item,'background')?`linear-gradient(0deg,#090c12cc,#090c1222),url('${asset(item,'background')}')`:''}>{#if asset(item,'icon')}<img src={asset(item,'icon')} alt=""/>{:else}<span>{item.name?.slice(0,1)||'X'}</span>{/if}<small>EXTERNAL</small></div><h3>{item.name}</h3><p>{item.source}</p><div><span>{item.path}</span><span>{item.port||'Port not set'}</span></div></a>{:else}<div class="discover-empty">Add or connect a repository to discover external plugins.</div>{/each}</section>
  {:else if view==='repositories'}
    <div class="toolbar"><button class="primary" on:click={()=>repoDialog=true}>+ Add repository</button></div>
    <div class="table"><table><thead><tr><th>Repository</th><th>Detected</th><th>Scan</th><th>Updated</th><th></th></tr></thead><tbody>{#each state.config.repositories as repo}<tr on:click={()=>location.href=`${base}/repository?id=${encodeURIComponent(repo.fullName)}`}><td><b>https://github.com/{repo.fullName}.git {#if repo.official}<em>Official</em>{/if}</b></td><td>{counts(repo)}</td><td>{repo.scanState||'not scanned'}</td><td>{repo.scannedAt?new Date(repo.scannedAt).toLocaleString():'â€”'}</td><td><button class="remove" on:click={(event)=>removeRepo(event,repo.fullName)}>Remove</button></td></tr>{:else}<tr><td colspan="5" class="empty">No repositories added.</td></tr>{/each}</tbody></table></div>
  {:else if view==='integrations'}
    <div class="toolbar"><button class="primary" on:click={()=>run(()=>api('actions',{method:'POST',body:JSON.stringify({action:'update-all-integrations'})}),'All integration updates queued.')}>Update all</button></div><div class="table"><table><thead><tr><th>Integration</th><th>Path</th><th>Installed</th><th>Available</th><th>Last change</th><th>Repository</th></tr></thead><tbody>{#each state.config.integrations as item}<tr on:click={()=>location.href=`${base}/integration?id=${encodeURIComponent(item.id)}`}><td><b>{item.name}</b><small>{item.domain}</small></td><td>{item.path}</td><td>{item.installedVersion||'â€”'}</td><td>{item.version||'â€”'}</td><td>{item.installedAt?new Date(item.installedAt).toLocaleString():'â€”'}</td><td>{item.repository}</td></tr>{:else}<tr><td colspan="6" class="empty">No integrations detected.</td></tr>{/each}</tbody></table></div>
  {:else if view==='applications'}
    <div class="table"><table><thead><tr><th>Application</th><th>Status</th><th>Port</th><th>Repository</th><th>Version</th></tr></thead><tbody>{#each state.config.apps as app}<tr on:click={()=>location.href=`${base}/application?id=${encodeURIComponent(app.id)}`}><td><b>{app.name}</b></td><td><span class:ok={state.status[app.id]?.state==='running'}>{state.status[app.id]?.state||'stopped'}</span></td><td>{app.port}</td><td>{app.repository}</td><td>{state.status[app.id]?.version||'â€”'}</td></tr>{:else}<tr><td colspan="5" class="empty">No applications installed.</td></tr>{/each}</tbody></table></div>
  {:else}
    <section class="settings"><article class="github-settings"><div class="settings-head"><div><p class="kicker">GITHUB CONNECTION</p><h2>GitHub account</h2><p>OAuth discovers repositories your account can access. Users never need to create or configure access tokens.</p></div><button class="primary oauth" on:click={deviceLogin}>Connect GitHub</button></div><div class="oauth-config"><label>OAuth App client ID<input bind:value={oauthClientId} placeholder={state.config.githubOAuthClientId||'GitHub OAuth App client ID'}/></label><button on:click={saveOAuth}>Save client ID</button></div>{#if device}<div class="device"><span>{device.user_code}</span><p>Enter this code on GitHub. Waiting for authorizationâ€¦</p></div>{/if}<div class="accounts"><h3>Connected accounts</h3>{#each state.config.githubAccounts as account}<div class="account"><span><b>{account.login}</b><small>GitHub OAuth</small></span><button on:click={()=>run(()=>api('settings',{method:'PUT',body:JSON.stringify({removeAccountId:account.id})}))}>Disconnect</button></div>{:else}<p>No GitHub account connected.</p>{/each}</div></article><article><h2>Home Assistant notifications</h2><p>Choose which events trigger a notification and who receives it.</p><h3>Events</h3><div class="toggles"><label><input type="checkbox" bind:checked={state.config.notifications.applicationErrors}/> Application install and runtime errors</label><label><input type="checkbox" bind:checked={state.config.notifications.applicationStopped}/> Applications that exit unexpectedly</label><label><input type="checkbox" bind:checked={state.config.notifications.repositoryErrors}/> Repository scan and Git pull errors</label><label><input type="checkbox" bind:checked={state.config.notifications.integrationErrors}/> Integration install and update errors</label><label><input type="checkbox" bind:checked={state.config.notifications.updatesAvailable}/> Available update notifications</label><label><input type="checkbox" bind:checked={state.config.notifications.successfulUpdates}/> Successful integration updates</label></div><h3>Recipients</h3><div class="recipients"><label><input type="checkbox" bind:checked={state.config.notifications.persistentNotification}/><span><b>Home Assistant</b><small>persistent_notification</small></span></label>{#each haNotifications.notifyServices as service}<label><input type="checkbox" checked={(state.config.notifications.notifyServices||[]).includes(service)} on:change={()=>toggleService(service)}/><span><b>{service.replaceAll('_',' ')}</b><small>notify.{service}</small></span></label>{/each}{#if !haNotifications.connected}<p>Notify services become available when the add-on is running inside Home Assistant.</p>{:else if !haNotifications.notifyServices.length}<p>No notify services were found in Home Assistant.</p>{/if}</div><button class="primary" on:click={saveNotifications}>Save notification preferences</button></article></section>
  {/if}
  {#if view==='settings'}<section class="settings update-settings"><article><h2>Update checks</h2><p>Checks detect new versions without installing integration updates automatically.</p><div class="row"><select bind:value={state.config.updateChecks.interval}><option value={2592000}>Monthly</option><option value={604800}>Weekly</option><option value={86400}>Daily</option><option value={43200}>Every 12 hours</option><option value={3600}>Hourly</option><option value={1800}>Every 30 minutes</option></select><button class="primary" on:click={saveUpdateInterval}>Save interval</button></div><small>Last check: {state.config.updateChecks.lastCheck?new Date(state.config.updateChecks.lastCheck).toLocaleString():'Not checked yet'}</small></article></section>{/if}
{#if repoDialog}<div class="modal-backdrop" role="presentation" on:click={(event)=>event.currentTarget===event.target&&(repoDialog=false)}><section class="repo-modal"><header><div><p class="kicker">REPOSITORY</p><h2>Add repository</h2></div><button on:click={()=>repoDialog=false}>Ã—</button></header><label>Repository type<select bind:value={repoMode}><option value="public">Public</option><option value="private">Private / GitHub account</option></select></label>{#if repoMode==='public'}<div class="repo-form"><h3>Add any public repository</h3><p>No GitHub login is required.</p><div class="row"><input bind:value={publicRepository} placeholder="owner/repository"/><button class="primary" on:click={()=>addRepo(publicRepository,'')}>Add</button></div></div>{:else}<div class="repo-form"><h3>Add from your GitHub account</h3><p>Choose a repository available to a connected account.</p><label>GitHub account<select bind:value={accountId}><option value="">Choose account</option>{#each state.config.githubAccounts as account}<option value={account.id}>{account.login}</option>{/each}</select></label><div class="row"><button on:click={loadRepos}>Load repositories</button><select bind:value={repository}><option value="">Choose repositoryâ€¦</option>{#each githubRepos as repo}<option value={repo.fullName}>{repo.fullName}</option>{/each}</select><button class="primary" on:click={()=>addRepo()}>Add</button></div></div>{/if}<button class="cancel" on:click={()=>repoDialog=false}>Cancel</button></section></div>{/if}
<style>
  h2{font-size:14px;margin:28px 0 10px}.table{border:1px solid #282f39;border-radius:8px;overflow:auto;background:#0e1319}table{width:100%;border-collapse:collapse;min-width:650px}th{text-align:left;color:#798493;font-size:10px;text-transform:uppercase;letter-spacing:.08em;padding:10px 13px;border-bottom:1px solid #282f39}td{padding:12px 13px;border-bottom:1px solid #202630;color:#aeb6c2}tr:last-child td{border-bottom:0}tbody tr{cursor:pointer}tbody tr:hover{background:#151b23}td b{display:block;color:#edf0f4}td small{display:block;color:#788391;margin-top:3px;max-width:500px}.empty{text-align:center;padding:34px}.toolbar,.row{display:flex;gap:8px;align-items:center;margin-bottom:14px}.toolbar select{max-width:280px}.flash{padding:9px 12px;background:#123328;color:#78e4ba;border:1px solid #275944;border-radius:6px;margin-bottom:12px}.flash.bad{background:#35171b;color:#f39ba5;border-color:#633039}.ok{color:#47e0a4}.danger,.metric-danger b{color:#ff7788!important}.hero{position:relative;overflow:hidden;border:1px solid #2a333d;border-radius:14px;padding:clamp(24px,5vw,48px);background:linear-gradient(125deg,#101922,#10141b);display:flex;align-items:center;justify-content:space-between;min-height:230px}.hero h2{font-size:clamp(25px,4vw,44px);letter-spacing:-.04em;max-width:680px;margin:5px 0 12px}.hero p{color:#9aa6b3;max-width:650px;line-height:1.6}.kicker{color:#45dda3!important;font-size:10px;font-weight:800;letter-spacing:.16em}.dashboard-hero>span{padding:8px 11px;border:1px solid #285d4b;background:#123026;color:#65e6b6;border-radius:99px}.discover-hero{background:radial-gradient(circle at 85% 45%,#214e48 0,transparent 32%),linear-gradient(120deg,#111922,#161323)}.orb{flex:0 0 150px;height:150px;border-radius:38%;display:grid;place-items:center;background:linear-gradient(145deg,#57e7b0,#278ccf);color:#071510;font-size:70px;font-weight:950;transform:rotate(8deg);box-shadow:0 20px 70px #42d7aa30}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0 25px}.metrics article{border:1px solid #28303a;border-radius:9px;padding:16px;background:#0e1319}.metrics small{color:#7f8a98}.metrics b{display:block;font-size:29px;margin-top:7px}.metrics i{font-size:14px;color:#697584;font-style:normal}.metrics p{margin:3px 0 0;color:#7e8997;font-size:11px}.dashboard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,420px),1fr));gap:14px}.dashboard-grid>section{min-width:0}.poster-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px}.poster-grid article{cursor:pointer;border-radius:11px;padding:11px;background:#0e1319;border:1px solid #272f39;transition:.18s transform,.18s border-color}.poster-grid article:hover{transform:translateY(-3px);border-color:#3c806a}.poster{aspect-ratio:16/10;border-radius:8px;padding:14px;display:flex;align-items:end;justify-content:space-between;background:radial-gradient(circle at 75% 20%,#4fa28b,transparent 35%),linear-gradient(140deg,#18352f,#181a29)}.poster>span{font-size:58px;font-weight:950;color:#65e4b7}.poster small{font-size:9px;letter-spacing:.12em}.poster.external{background:linear-gradient(140deg,#262c38,#171b22)}.poster-grid h3{margin:12px 0 5px}.poster-grid p{color:#8995a3;line-height:1.4;min-height:38px}.poster-grid article>div:last-child{display:flex;gap:6px;flex-wrap:wrap}.poster-grid article>div:last-child span{font-size:10px;color:#8d98a5;background:#171e26;padding:4px 6px;border-radius:4px}.discover-empty{grid-column:1/-1;border:1px dashed #323b47;padding:35px;text-align:center;color:#808c9b;border-radius:9px}.repository-add{display:grid;grid-template-columns:1fr 1.3fr;gap:12px;margin-bottom:16px}.repository-add>div{border:1px solid #29313b;background:#0e1319;border-radius:9px;padding:16px}.repository-add h2{margin:0 0 5px}.repository-add p{color:#8994a2}.settings{display:grid;gap:14px;max-width:900px}.settings article{border:1px solid #282f39;background:#0e1319;padding:20px;border-radius:9px}.settings h2{margin-top:0}.settings p{color:#929dab}.settings-lead{display:flex;align-items:center;justify-content:space-between;gap:24px;background:linear-gradient(110deg,#10201d,#11151c)!important}.oauth{white-space:nowrap;padding:11px 17px!important}.account{display:flex;justify-content:space-between;padding:10px 0;border-top:1px solid #242b34}.account span{display:grid}.account small{color:#7e8997}.device{padding:14px;background:#101b21;border-radius:7px}.device span{font:700 24px ui-monospace,monospace;letter-spacing:.12em}.toggles{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:14px 0}.toggles label{display:flex;gap:9px;align-items:center;color:#b0b8c4;padding:9px;border:1px solid #252d37;border-radius:6px}.toggles input{width:auto}@media(max-width:850px){.metrics{grid-template-columns:1fr 1fr}.dashboard-grid,.repository-add{grid-template-columns:1fr}.orb{display:none}}@media(max-width:700px){.toolbar,.row{align-items:stretch;flex-direction:column}.toolbar select{max-width:none}.settings-lead{align-items:stretch;flex-direction:column}.toggles{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}}
  .poster-grid a{cursor:pointer;border-radius:11px;padding:11px;background:#0e1319;border:1px solid #272f39;transition:.18s transform,.18s border-color}.poster-grid a:hover{transform:translateY(-3px);border-color:#da3}.poster-grid a>div:last-child{display:flex;gap:6px;flex-wrap:wrap}.poster-grid a>div:last-child span{font-size:10px;color:#8d98a5;background:#171e26;padding:4px 6px;border-radius:4px}
  .settings-head{display:flex;align-items:center;justify-content:space-between;gap:20px}.oauth-config{display:grid;grid-template-columns:1fr auto;align-items:end;gap:8px;margin:18px -20px;padding:14px 20px;border:solid #272f38;border-width:1px 0;border-radius:0;background:#0b1016}.oauth-config label{display:grid;gap:6px;color:#929dab}.accounts h3,.settings article>h3{font-size:12px;color:#b8c0ca;margin:18px 0 8px}.recipients{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0 17px}.recipients>label{display:flex;align-items:center;gap:10px;padding:10px;border:1px solid #29313b;border-radius:7px}.recipients input{width:auto}.recipients span{display:grid}.recipients small{color:#7e8997}.recipients p{grid-column:1/-1}
  .poster.has-image{background-position:center;background-size:cover}.poster img{width:64px;height:64px;object-fit:contain;border-radius:14px;background:#0b0d12cc;padding:7px;filter:drop-shadow(0 8px 18px #0008)}.row:last-child{margin-bottom:0}
  td em{display:inline-block;margin-left:7px;padding:3px 6px;border:1px solid #69591d;border-radius:99px;color:#da3;font-size:9px;font-style:normal;text-transform:uppercase}.remove{padding:4px 7px;color:#d98b95;background:transparent;border-color:#513039}
  /* OsaÃ¼hing X CVI */
  .kicker,.ok,.metrics b,.poster>span{color:#da3!important}
  .dashboard-hero>span{color:#da3;border-color:#66551d;background:#28220e}
  .orb{background:linear-gradient(145deg,#f0c94b,#b88612);color:#191405;box-shadow:0 20px 70px #ddaA3338}
  .poster{background:radial-gradient(circle at 75% 20%,#9b7f25,transparent 35%),linear-gradient(140deg,#332d19,#181a29)}
  @media(max-width:700px){.settings-head{align-items:stretch;flex-direction:column}.oauth-config,.recipients{grid-template-columns:1fr}}
  .update-settings{margin-top:14px}.modal-backdrop{position:fixed;inset:0;z-index:90;background:#000b;backdrop-filter:blur(4px);display:grid;place-items:center;padding:18px}.repo-modal{width:min(620px,100%);padding:22px;border:1px solid #303844;border-radius:12px;background:#0e1319;box-shadow:0 28px 90px #000}.repo-modal>header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.repo-modal>header h2{font-size:22px;margin:2px 0}.repo-modal>label,.repo-form>label{display:grid;gap:7px;color:#929dab}.repo-form{display:grid;gap:10px;margin-top:16px;padding:17px;border:1px solid #29313b;border-radius:8px}.repo-form h3,.repo-form p{margin:0}.repo-form p{color:#929dab}.repo-form .row{margin:0}.cancel{margin-top:14px;width:100%}@media(max-width:700px){.repo-form .row{display:flex;flex-direction:column}}
  .update-settings .primary,.repo-form .row>button:first-child{white-space:nowrap}.repo-form{margin-left:-22px;margin-right:-22px;padding-left:22px;padding-right:22px;border-radius:0;border-width:1px 0}@media(max-width:900px){.dashboard-grid{grid-template-columns:1fr}}
</style>


